SELECT count(*) FROM public.title title WHERE EXISTS (SELECT 1 FROM public.aka_name an, public.char_name chn, public.cast_info ci, public.company_name cn, public.info_type it, public.movie_companies mc, public.movie_info mi, public.name n, public.role_type rt WHERE title.id = mi.movie_id AND title.id = mc.movie_id AND title.id = ci.movie_id AND cn.id = mc.company_id AND it.id = mi.info_type_id AND n.id = ci.person_id AND rt.id = ci.role_id AND n.id = an.person_id AND chn.id = ci.person_role_id AND cn.country_code = '[us]' AND it.info = 'release dates' AND n.gender = 'f' AND rt.role = 'actress' AND title.production_year > 2000);
